import * as THREE from 'three'
import data from '../data/plodder-cavities.json'

/**
 * Measured geometry for the pre-plodder, vacuum chamber, final plodder and cone
 * heater - the four machines at the end of the line.
 *
 * The JSON is generated by scripts/extract-plodder-cavities.mjs and holds
 * coordinates in each anchor MESH'S OWN local space. Resolving them here,
 * against the anchor's live transform, is what makes the data survive a
 * re-export that changes the model's scale, orientation or node tree - which has
 * already happened once.
 *
 * Distinct from dieHoles.ts, which measures the NOODLER's die (ASD12_A18_0) and
 * the belt it feeds. The noodler and the pre-plodder are the same CAD part
 * duplicated along the line, so the two modules share technique but no data.
 */

// ── shared ───────────────────────────────────────────────────────────────────

// `object`'s transform as if `scene` were sitting at the identity transform.
// Everything in this viewer is a child of the loaded scene and works in this
// space - see the same helper in GateHinge, MixerFill, hopperSurface and
// dieHoles. Using matrixWorld here instead would double-apply the model's own
// position offset, which App.tsx sets to stand the machine on the ground.
function getSceneRelativeMatrix(object: THREE.Object3D, scene: THREE.Object3D, target: THREE.Matrix4) {
  scene.updateWorldMatrix(true, false)
  object.updateWorldMatrix(true, false)
  return target.copy(scene.matrixWorld).invert().multiply(object.matrixWorld)
}

/**
 * The anchor mesh's placement, or null if it cannot be trusted.
 *
 * Null means "draw nothing". Material rendered in the wrong place is worse than
 * no material at all, because a plant viewer showing product somewhere it is not
 * is actively misleading, where a missing feature is merely incomplete.
 *
 * The vertex-count check is the guard that matters: a re-export that keeps the
 * node name but changes the geometry would leave every measured coordinate
 * silently stale, and nothing about the result would look obviously wrong.
 */
export interface AnchorPlacement {
  mesh: THREE.Mesh
  /** Local -> scene-relative. Carries the model's own scale and orientation. */
  matrix: THREE.Matrix4
  /** Uniform scale factor from local units to scene units. */
  scale: number
}

export function resolveAnchor(
  scene: THREE.Object3D | null,
  name: string,
  expectedVertexCount: number,
): AnchorPlacement | null {
  if (!scene) return null
  const object = scene.getObjectByName(name)
  if (!object || !(object as THREE.Mesh).isMesh) {
    console.warn(`[plodder] anchor mesh "${name}" not found; skipping.`)
    return null
  }
  const mesh = object as THREE.Mesh
  const actual = mesh.geometry.attributes.position?.count ?? 0
  if (actual !== expectedVertexCount) {
    console.warn(
      `[plodder] anchor mesh "${name}" has ${actual} vertices, ` +
      `data was measured against ${expectedVertexCount}; skipping. ` +
      'Re-run `npm run extract:plodder-cavities`.',
    )
    return null
  }
  const matrix = getSceneRelativeMatrix(mesh, scene, new THREE.Matrix4())
  const scale = new THREE.Vector3().setFromMatrixScale(matrix).x
  return { mesh, matrix, scale }
}

// ── vertical profiles (chamber, hopper) ──────────────────────────────────────
// Both sweep along local y, so their cross-sections are (z, x) - the two axes
// that follow y cyclically, which is the order the extraction script emits.

/** Cross-section of a vertical-axis vessel, in the anchor's local units. */
export interface VerticalSection {
  cz: number
  cx: number
  rz: number
  rx: number
}

type VerticalRow = [y: number, cz: number, cx: number, rz: number, rx: number]

/**
 * Cross-section at `y`, linearly interpolated between measured levels.
 *
 * Clamps to the lowest level below the range; returns null above the top, since
 * there is no vessel there to interpolate toward - an open feed mouth is not a
 * wall, and pretending otherwise would let material stack into thin air.
 */
function verticalSectionAt(profile: readonly VerticalRow[], y: number): VerticalSection | null {
  if (profile.length === 0) return null
  if (y <= profile[0][0]) {
    const [, cz, cx, rz, rx] = profile[0]
    return { cz, cx, rz, rx }
  }
  for (let i = 1; i < profile.length; i++) {
    const [y1, cz1, cx1, rz1, rx1] = profile[i]
    if (y > y1) continue
    const [y0, cz0, cx0, rz0, rx0] = profile[i - 1]
    const t = y1 === y0 ? 0 : (y - y0) / (y1 - y0)
    return {
      cz: cz0 + (cz1 - cz0) * t,
      cx: cx0 + (cx1 - cx0) * t,
      rz: rz0 + (rz1 - rz0) * t,
      rx: rx0 + (rx1 - rx0) * t,
    }
  }
  return null
}

// ── the pre-plodder die ──────────────────────────────────────────────────────

const die = data.die

/** Anchor mesh name and vertex count, for resolveAnchor. */
export const DIE_MESH = die.mesh.name
export const DIE_VERTEX_COUNT = die.mesh.vertexCount

/**
 * The local axis material travels along, and its sign.
 *
 * Derived by the extraction script from where the final plodder screws actually
 * sit, not transcribed: this subassembly is mirrored relative to the machine the
 * animation was first written for, so a copied sign would extrude the noodles
 * backwards into the machine.
 */
export const DIE_FLOW_AXIS = die.flowAxis as 'x' | 'y' | 'z'
export const DIE_FLOW_SIGN = die.flowSign
/** The two local axes the plate's face spans, in the order `holes` pairs them. */
export const DIE_FACE_AXES = die.faceAxes as ['x' | 'y' | 'z', 'x' | 'y' | 'z']
/** Local coordinate, along the flow axis, of the face noodles emerge from. */
export const DIE_FACE_LOCAL = die.downstreamFaceLocal
/** Hole radius in die-local units. All holes are uniform (stddev 0.54%). */
export const DIE_HOLE_RADIUS = die.holeRadiusLocal

// Cast through `unknown`: TypeScript widens the imported JSON's fixed-length
// rows to number[], which is not assignable to a tuple. The extraction script
// emits exactly these arities and the shapes are asserted there, so the tuple
// types are the honest description of the data even though the import loses them.
const holes = die.holes as unknown as readonly (readonly [u: number, v: number, clearance: number])[]

/** Every hole, open or not: `[u, v, clearance]` in die-local units. */
export const DIE_HOLES = holes

/**
 * Holes with a clear run downstream, so strands do not extrude into metal.
 *
 * The plate spans the full bore and the collars carrying the screws sit directly
 * behind part of it. The distribution is sharply bimodal - blocked holes stop
 * within 0.033 local units, open ones run past 1.0 to the chamber wall - so any
 * threshold between the two modes selects the same 208 of 278.
 */
export function usableHoles(minClearance = 1.0): readonly (readonly [number, number, number])[] {
  return holes.filter((h) => h[2] >= minClearance)
}

// ── the cavity below the die ─────────────────────────────────────────────────
// Where extruded noodles fall and heap up, on top of the final plodder screws.
// Measured in DIE-local space, so it shares an anchor with the strands feeding
// it - the two must not be able to disagree about where the material lands.
//
// A funnel, not a floor: narrow at the screws, widening upward, with its centre
// drifting as it rises. Material filling a vessel takes the vessel's shape, so
// the heap is placed by sampling this rather than by heaping a cone on a plane.

const chamber = data.chamber.profile as unknown as readonly VerticalRow[]

export const CHAMBER_PROFILE = chamber
/** Lowest measured level - the throat between the final plodder screws. */
export const CHAMBER_FLOOR_Y = chamber[0][0]
/** Highest measured level, just under the die. */
export const CHAMBER_TOP_Y = chamber[chamber.length - 1][0]

export function chamberSectionAt(y: number): VerticalSection | null {
  return verticalSectionAt(chamber, y)
}

// ── the pre-plodder hopper ───────────────────────────────────────────────────
// A funnel opening from a narrow throat at the screws to the brim, about a
// centre that barely moves. A fill drawn as a cylinder would float clear of the
// sloping walls at every level below the top.

const hopper = data.hopper
const hopperProfile = hopper.profile as unknown as readonly VerticalRow[]

export const HOPPER_MESH = hopper.mesh.name
export const HOPPER_VERTEX_COUNT = hopper.mesh.vertexCount
export const HOPPER_PROFILE = hopperProfile
/** The outlet, where material leaves for the screws. */
export const HOPPER_FLOOR_Y = hopperProfile[0][0]
/**
 * The brim, which 100% level maps to.
 *
 * Not the mesh's bounding-box top: above this the shell opens out into the feed
 * mouth, and material above the opening would be outside the vessel.
 */
export const HOPPER_BRIM_Y = hopperProfile[hopperProfile.length - 1][0]

export function hopperSectionAt(y: number): VerticalSection | null {
  return verticalSectionAt(hopperProfile, y)
}

// ── the cone heater bore ─────────────────────────────────────────────────────
// Downstream of the final plodder, material is squeezed through the cone into a
// bar. The bore sweeps along local z, so its cross-sections are (x, y).
//
// Measured, not assumed to be a cone of revolution: it starts as a wide flat
// ellipse matching the twin-screw discharge (0.720 x 0.359 local) and closes to
// a circle at the nozzle (0.323 x 0.323). A solid filling it has to take its two
// radii per ring from here.

const cone = data.cone
type ConeRow = [z: number, cx: number, cy: number, rx: number, ry: number]
const coneProfile = cone.profile as unknown as readonly ConeRow[]

export const CONE_MESH = cone.mesh.name
export const CONE_VERTEX_COUNT = cone.mesh.vertexCount
export const CONE_PROFILE = coneProfile
/** Where the twin screws discharge into the cone. */
export const CONE_INLET_Z = coneProfile[0][0]
/** The nozzle. */
export const CONE_OUTLET_Z = coneProfile[coneProfile.length - 1][0]

/** Cross-section of the cone bore, in cone-local units. */
export interface ConeSection {
  cx: number
  cy: number
  rx: number
  ry: number
}

/** Cross-section at local `z`, linearly interpolated and clamped to the bore. */
export function coneSectionAt(z: number): ConeSection {
  const first = coneProfile[0]
  if (z <= first[0]) return { cx: first[1], cy: first[2], rx: first[3], ry: first[4] }
  for (let i = 1; i < coneProfile.length; i++) {
    const [z1, cx1, cy1, rx1, ry1] = coneProfile[i]
    if (z > z1) continue
    const [z0, cx0, cy0, rx0, ry0] = coneProfile[i - 1]
    const t = z1 === z0 ? 0 : (z - z0) / (z1 - z0)
    return {
      cx: cx0 + (cx1 - cx0) * t,
      cy: cy0 + (cy1 - cy0) * t,
      rx: rx0 + (rx1 - rx0) * t,
      ry: ry0 + (ry1 - ry0) * t,
    }
  }
  const last = coneProfile[coneProfile.length - 1]
  return { cx: last[1], cy: last[2], rx: last[3], ry: last[4] }
}

// ── provenance ───────────────────────────────────────────────────────────────

/** The GLB the measurements were taken from, for logging on a mismatch. */
export const SOURCE_FILE = data.source.file
